SET ROLE service_role;
DO $$
DECLARE customer uuid:='10000000-0000-4000-8000-000000000001'; admin uuid:='10000000-0000-4000-8000-000000000002';
 other_customer uuid:='10000000-0000-4000-8000-000000000003';device uuid; other_device uuid; c jsonb; next_case jsonb; job jsonb; loan uuid; key uuid:=gen_random_uuid();
BEGIN
 INSERT INTO public.lending_push_devices(user_id,token,platform) VALUES(customer,'local-fixture-push-token-customer-001','android') RETURNING id INTO device;
 INSERT INTO public.lending_push_devices(user_id,token,platform) VALUES(other_customer,'local-fixture-push-token-other-001','android') RETURNING id INTO other_device;
 c:=lending_support_create(customer,'{"reason":"ungraded","cardName":"通知テスト","cardNumber":"","condition":"","notes":"","requestedAmount":"","consent":true}',gen_random_uuid());
 ASSERT NOT EXISTS(SELECT 1 FROM public.lending_status_notifications WHERE entity_id=(c->>'id')::uuid),'no redundant initial consultation push';
 c:=lending_support_command(admin,(c->>'id')::uuid,'review','{"message":"写真確認"}',key,1);
 PERFORM lending_support_command(admin,(c->>'id')::uuid,'review','{"message":"写真確認"}',key,1);
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_id=(c->>'id')::uuid)=1,'idempotent event';
 ASSERT (SELECT count(*) FROM public.lending_push_deliveries)=1,'owner device only';
 ASSERT NOT EXISTS(SELECT 1 FROM public.lending_push_deliveries WHERE device_id=other_device);
 job:=lending_claim_status_push(5,'case',(c->>'id')::uuid)->0;ASSERT job->>'token'='local-fixture-push-token-customer-001';
 ASSERT jsonb_array_length(lending_claim_status_push(5,'case',(c->>'id')::uuid))=0,'concurrent claim cannot resend';
 PERFORM lending_finish_status_push((job->>'id')::uuid,gen_random_uuid(),'wrong-lease',NULL);
 ASSERT (SELECT status FROM public.lending_push_deliveries WHERE id=(job->>'id')::uuid)='sending','lease fencing';
 PERFORM lending_finish_status_push((job->>'id')::uuid,(job->>'leaseId')::uuid,NULL,'fcm_send_failed');
 ASSERT (SELECT status='pending' AND total_attempts=1 FROM public.lending_push_deliveries WHERE id=(job->>'id')::uuid),'failed delivery is durable';
 ASSERT (SELECT status FROM public.lending_support_cases WHERE id=(c->>'id')::uuid)='reviewing','failed push cannot roll back status';
 PERFORM lending_retry_status_push(admin,'case',(c->>'id')::uuid);
 job:=lending_claim_status_push(5,'case',(c->>'id')::uuid)->0;
 PERFORM lending_finish_status_push((job->>'id')::uuid,(job->>'leaseId')::uuid,'projects/local/messages/accepted',NULL);
 PERFORM lending_retry_status_push(admin,'case',(c->>'id')::uuid);
 ASSERT jsonb_array_length(lending_claim_status_push(5,'case',(c->>'id')::uuid))=0,'accepted messages cannot be retried';
 c:=lending_support_command(admin,(c->>'id')::uuid,'review','{"message":"同じ状態での追記"}',gen_random_uuid(),2);
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_id=(c->>'id')::uuid)=1,'same status does not create a notification';
 BEGIN PERFORM lending_support_command(admin,(c->>'id')::uuid,'request_info','{"message":"失敗する競合更新"}',gen_random_uuid(),1);EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='version_conflict';END;
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_id=(c->>'id')::uuid)=1,'failed transaction cannot enqueue';
 c:=lending_support_command(admin,(c->>'id')::uuid,'request_info','{"message":"追加写真をお願いします"}',gen_random_uuid(),3);
 job:=lending_claim_status_push(5,'case',(c->>'id')::uuid)->0;
 PERFORM lending_finish_status_push((job->>'id')::uuid,(job->>'leaseId')::uuid,NULL,'device_not_registered');
 ASSERT (SELECT token LIKE 'disabled:%' FROM public.lending_push_devices WHERE id=device),'unregistered token disabled';
 BEGIN PERFORM lending_revert_case_status(admin,(c->>'id')::uuid,'reviewing','',4,gen_random_uuid());RAISE EXCEPTION 'unsafe';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='reason_required';END;
 c:=lending_revert_case_status(admin,(c->>'id')::uuid,'reviewing','写真を再確認します',4,gen_random_uuid());
 ASSERT c->>'status'='reviewing' AND c->>'offer_jpy' IS NULL;
 ASSERT EXISTS(SELECT 1 FROM public.lending_support_events WHERE case_id=(c->>'id')::uuid AND action='rollback');
 ASSERT EXISTS(SELECT 1 FROM public.lending_status_notifications WHERE entity_id=(c->>'id')::uuid AND to_status='reviewing' AND entity_version=5),'rollback also enqueues notification';
 next_case:=lending_support_create(admin,'{"reason":"ungraded","cardName":"未紐付け","cardNumber":"","condition":"","notes":"","requestedAmount":"","consent":true}',gen_random_uuid());
 PERFORM lending_support_command(admin,(next_case->>'id')::uuid,'review','{"message":"未紐付け写真確認"}',gen_random_uuid(),1);
 ASSERT NOT EXISTS(SELECT 1 FROM public.lending_status_notifications WHERE entity_id=(next_case->>'id')::uuid),'unlinked cases do not notify arbitrary users';
 BEGIN PERFORM lending_retry_status_push(customer,'case',(c->>'id')::uuid);RAISE EXCEPTION 'unsafe';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='forbidden';END;
 INSERT INTO public.lending_push_devices(user_id,token,platform) VALUES(customer,'local-fixture-push-token-customer-002','android');
 next_case:=lending_support_create(customer,'{"reason":"ungraded","cardName":"契約側の通知テスト","cardNumber":"","condition":"","notes":"","requestedAmount":"100000","consent":true}',gen_random_uuid());
 next_case:=lending_support_command(admin,(next_case->>'id')::uuid,'review','{"message":"確認"}',gen_random_uuid(),1);
 next_case:=lending_support_command(admin,(next_case->>'id')::uuid,'offer','{"message":"評価根拠","amountJpy":100000,"valuationJpy":200000}',gen_random_uuid(),2);
 next_case:=lending_support_command(customer,(next_case->>'id')::uuid,'accept','{"amountJpy":100000,"deposit":"mail","termsAccepted":true}',gen_random_uuid(),3);loan:=(next_case->>'loan_id')::uuid;
 ASSERT NOT EXISTS(SELECT 1 FROM public.lending_status_notifications WHERE entity_id=(next_case->>'id')::uuid AND to_status='applied'),'case-to-loan conversion not duplicated';
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_kind='loan' AND entity_id=loan)=1,'initial application notification';
 PERFORM lending_command(admin,loan,'receive','{"location":"LOCAL","inspected":true}',gen_random_uuid(),1);
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_kind='loan' AND entity_id=loan AND to_status='received')=1,'loan status updates notify';
 BEGIN PERFORM lending_command(admin,loan,'fund','{"amountJpy":100000,"reference":"INVALID-FUND"}',gen_random_uuid(),2);EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='invalid_transition';END;
 ASSERT (SELECT count(*) FROM public.lending_status_notifications WHERE entity_kind='loan' AND entity_id=loan)=2,'rejected financial changes cannot notify';
 RAISE NOTICE 'Transactional queue, owner-only fan-out, event idempotency, leases, retry, invalid tokens, no-device and status persistence passed.';
END $$;
RESET ROLE;
SET ROLE authenticated;
DO $$ BEGIN
 BEGIN PERFORM id FROM public.lending_status_notifications;RAISE EXCEPTION 'unsafe';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM id FROM public.lending_push_deliveries;RAISE EXCEPTION 'unsafe';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM lending_claim_status_push();RAISE EXCEPTION 'unsafe';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
